package com.lolfm.simulator;
import com.lolfm.domain.*;import java.util.*;import java.util.function.Function;
public final class LateGameMacroDiagnostics{
 public static void main(String[]args){System.out.println("LATE_GAME_MACRO_DIAGNOSTICS structured=true constantsTuned=false");for(Scenario s:scenarios()){run(s,false,1000);run(s,true,1000);if(!s.key.equals("A")){run(s.mirrored(),false,500);run(s.mirrored(),true,500);}}focused();}
 private static void run(Scenario scenario,boolean enabled,int seeds){Aggregate a=new Aggregate(scenario.key+(scenario.isMirror?"-MIRROR":"")+(enabled?"-ON":"-OFF"));for(int seed=1;seed<=seeds;seed++){MatchSimulator simulator=simulator(SimulationOptions.productionDefaults().withLateGameMacroEnabled(enabled).withDiagnosticsEnabled(true));MatchSimulator.SimulationResult result=simulator.simulateWithDiagnostics(scenario.team(TeamSide.BLUE),scenario.team(TeamSide.RED),seed);a.add(result.timeline(),result.structureActionExecutionStats());}a.print();}
 private static MatchSimulator simulator(SimulationOptions o){return new MatchSimulator(new TeamfightResolver(),new EndGameEvaluator(),new SnapshotFactory(),new ObjectiveResolver(),new PostFightResolver(),new ObjectiveAttemptResolver(),new StructureResolver(),new PushResolver(),o);}
 private static void focused(){System.out.println("FOCUSED");GameState s=LateGameTestSupport.state();LateGameTestSupport.midGameAt(s,1799);System.out.println("29:59 phase="+s.getLanePhaseState().getMatchPhase());s.advanceTimeSeconds(1);new LateGameMacroResolver().transitionIfDue(s,new MidGameMacroResolver());System.out.println("30:00 phase="+s.getLanePhaseState().getMatchPhase()+" next="+s.getLateGameState().getNextEvaluationAtSeconds()+" decision="+s.getLateGameState().getLatestDecision());for(TeamSide side:TeamSide.values())System.out.println("base "+side+"="+new BaseThreatEvaluator().evaluate(s,side));GameState exposed=LateGameTestSupport.state();LateGameTestSupport.destroyThroughInhibitorTower(exposed,TeamSide.RED,Lane.MID);System.out.println("inhibitor-exposed="+new BaseThreatEvaluator().evaluate(exposed,TeamSide.RED));exposed.getMapState().getLaneState(TeamSide.RED,Lane.MID).destroyInhibitor(900);System.out.println("nexus-turret-threat="+new BaseThreatEvaluator().evaluate(exposed,TeamSide.RED));exposed.getMapState().getBaseState(TeamSide.RED).destroyOneNexusTurret();System.out.println("one-nexus-turret="+new BaseThreatEvaluator().evaluate(exposed,TeamSide.RED));exposed.getMapState().getBaseState(TeamSide.RED).destroyOneNexusTurret();System.out.println("nexus-exposed="+new BaseThreatEvaluator().evaluate(exposed,TeamSide.RED));}
 private static List<Scenario> scenarios(){Profile equal=Profile.all(14,14,14,14);return List.of(new Scenario("A",equal,equal,false),new Scenario("B",Profile.all(18,16,18,18),Profile.all(10,12,10,10),false),new Scenario("C",Profile.lanes(16,14,18,14,14,14,14,14),Profile.lanes(12,14,10,14,14,14,14,14),false),new Scenario("D",Profile.all(14,16,14,18),Profile.all(14,12,14,10),false),new Scenario("E",Profile.all(10,12,10,10),Profile.all(18,16,18,18),false),new Scenario("F",Profile.lanes(16,14,18,12,14,12,14,10),Profile.all(14,16,14,18),false),new Scenario("G",Profile.all(18,18,18,18),Profile.all(10,10,10,10),false));}
 private record Scenario(String key,Profile blue,Profile red,boolean isMirror){Scenario mirrored(){return new Scenario(key,red,blue,true);}Team team(TeamSide side){Profile p=side==TeamSide.BLUE?blue:red;String prefix=(side==TeamSide.BLUE?"BLUE":"RED")+"-"+key+(isMirror?"M":"");List<Player> players=new ArrayList<>();for(Position pos:Position.values()){int[]v=p.values.get(pos);players.add(new Player(prefix+"-"+pos,pos,new PlayerAttributes(v[0],v[1],v[2],v[3])));}return new Team(prefix,players);}}
 private static final class Profile{final EnumMap<Position,int[]>values=new EnumMap<>(Position.class);static Profile all(int m,int a,int f,int t){Profile p=new Profile();for(Position pos:Position.values())p.values.put(pos,new int[]{m,a,f,t});return p;}static Profile lanes(int lm,int la,int lf,int lt,int jm,int ja,int jf,int jt){Profile p=new Profile();for(Position pos:Position.values())p.values.put(pos,(pos==Position.TOP||pos==Position.MID||pos==Position.ADC)?new int[]{lm,la,lf,lt}:new int[]{jm,ja,jf,jt});return p;}}
 private static final class Aggregate{final String name;int games,transitions,early,time,evaluations,noInitiative,resets,actions,lateFights,lateStructures,crossSuccess,crossFail,nexusFinish,nexusDestroyed,timeouts,blueWins,redWins,offMutations;long structureAttempted,structureMutationPerformed,laterResolverBlockedByAttempt,sameSideMultipleAttemptError,sameSideMultipleMutationError,postFightMultiStructureActions,postFightMultiStructureMutationCount,postFightInternalBlockError;long transitionTime,duration;final EnumMap<LateGameAttackPlan,Integer>plans=new EnumMap<>(LateGameAttackPlan.class);final EnumMap<LateGameDefenseResponse,Integer>responses=new EnumMap<>(LateGameDefenseResponse.class);final EnumMap<LateGameActionResult,Integer>results=new EnumMap<>(LateGameActionResult.class);final EnumMap<BaseThreatLevel,Integer>threats=new EnumMap<>(BaseThreatLevel.class);Aggregate(String n){name=n;}void add(MatchTimeline t,StructureActionExecutionStatsSnapshot structureStats){games++;structureAttempted+=structureStats.structureAttempted();structureMutationPerformed+=structureStats.structureMutationPerformed();laterResolverBlockedByAttempt+=structureStats.laterResolverBlockedByAttempt();sameSideMultipleAttemptError+=structureStats.sameSideMultipleAttemptError();sameSideMultipleMutationError+=structureStats.sameSideMultipleMutationError();postFightMultiStructureActions+=structureStats.postFightMultiStructureActions();postFightMultiStructureMutationCount+=structureStats.postFightMultiStructureMutationCount();postFightInternalBlockError+=structureStats.postFightInternalBlockError();duration+=t.getDurationSeconds();if(t.getWinner()==null)timeouts++;else if(t.getWinner().startsWith("BLUE"))blueWins++;else redWins++;MatchSnapshot end=t.getSnapshots().getLast();LateGameSnapshot late=end.getLateGame();if(late.lateGameStartedAtSeconds()>=0){transitions++;transitionTime+=late.lateGameStartedAtSeconds();if(late.transitionReason()==LateGameTransitionReason.TIME_LIMIT)time++;else early++;}for(MatchSnapshot x:t.getSnapshots()){LateGameSnapshot l=x.getLateGame();threats.merge(l.blueBaseThreat().overallLevel(),1,Integer::sum);threats.merge(l.redBaseThreat().overallLevel(),1,Integer::sum);}Set<Integer> seenDecisions=new HashSet<>();for(MatchSnapshot x:t.getSnapshots()){LateGameDecisionData d=x.getLateGame().latestDecision();if(d!=null&&seenDecisions.add(d.sequence())){evaluations++;if(d.result()==LateGameActionResult.NO_INITIATIVE)noInitiative++;if(d.selectedAttackPlan()==LateGameAttackPlan.RESET_AND_REGROUP){resets++;plans.merge(LateGameAttackPlan.RESET_AND_REGROUP,1,Integer::sum);}}}for(MatchEvent e:t.getEvents()){LateGameDecisionData d=e.getLateGameDecision();if(d!=null){actions++;if(d.selectedAttackPlan()!=null)plans.merge(d.selectedAttackPlan(),1,Integer::sum);if(d.selectedDefenseResponse()!=null)responses.merge(d.selectedDefenseResponse(),1,Integer::sum);results.merge(d.result(),1,Integer::sum);if(d.majorCombatConsumed())lateFights++;if(d.crossMapRollExecuted()){if(d.crossMapSucceeded())crossSuccess++;else crossFail++;}if(d.selectedAttackPlan()==LateGameAttackPlan.NEXUS_FINISH)nexusFinish++;}if(e.getStructureActionSource()==StructureActionSource.LATE_GAME_SIEGE||e.getStructureActionSource()==StructureActionSource.LATE_GAME_CROSS_MAP||e.getStructureActionSource()==StructureActionSource.NEXUS_FINISH){lateStructures++;if(e.getStructureKind()==StructureKind.NEXUS)nexusDestroyed++;}}if(!late.enabled() && (late.latestDecision()!=null || t.getEvents().stream().anyMatch(e -> e.getType()==MatchEventType.LATE_GAME_ACTION || e.getStructureActionSource()==StructureActionSource.LATE_GAME_SIEGE || e.getStructureActionSource()==StructureActionSource.LATE_GAME_CROSS_MAP || e.getStructureActionSource()==StructureActionSource.NEXUS_FINISH))) offMutations++;}void print(){System.out.printf(Locale.ROOT,"%s games=%d transition=%d avgTransition=%.1f time=%d early=%d evaluations=%d noInitiative=%d resets=%d actions=%d fights=%d structures=%d cross=%d/%d finish=%d nexus=%d W=%d/%d timeout=%d avgDuration=%.1f offMutation=%d structure={attempted=%d,mutation=%d,blocked=%d,multiAttemptError=%d,multiMutationError=%d,postFightMultiActions=%d,postFightMultiMutations=%d,postFightInternalBlockError=%d} plans=%s defense=%s result=%s threat=%s%n",name,games,transitions,transitions==0?0:transitionTime/(double)transitions,time,early,evaluations,noInitiative,resets,actions,lateFights,lateStructures,crossSuccess,crossFail,nexusFinish,nexusDestroyed,blueWins,redWins,timeouts,duration/(double)games,offMutations,structureAttempted,structureMutationPerformed,laterResolverBlockedByAttempt,sameSideMultipleAttemptError,sameSideMultipleMutationError,postFightMultiStructureActions,postFightMultiStructureMutationCount,postFightInternalBlockError,plans,responses,results,threats);}}
}
